function calculator(){closeOverlays();const n=document.createElement("div");n.id="calculatorPanel";n.className="overlay-panel";n.innerHTML='<div class="panel-head"><b>Calculator</b><button id="closeCalc" class="icon-btn">×</button></div><input id="calcDisplay" class="calc-display mono" readonly aria-label="Calculator display"><div class="calc-grid">'+["7","8","9","÷","4","5","6","×","1","2","3","−","0",".","(",")","+","⌫","=","C"].map(v=>`<button class="calc-key" data-calc="${v}">${v}</button>`).join("")+"</div>";document.body.append(n);let e="";const d=n.querySelector("#calcDisplay");n.querySelector("#closeCalc").onclick=()=>n.remove();n.querySelectorAll("[data-calc]").forEach(b=>b.onclick=()=>{const v=b.dataset.calc;if(v==="C")e="";else if(v==="⌫")e=e.slice(0,-1);else if(v==="="){try{e=String(calcEval(e))}catch(_){e="Error"}}else e=e==="Error"?v:e+v;d.value=e})}
function calcEval(e){const x=e.replaceAll("×","*").replaceAll("÷","/").replaceAll("−","-");if(!x||!/^[0-9+*/(). -]+$/.test(x))throw Error();const t=x.match(/\d+(?:\.\d+)?|[()+\-*/]/g)||[],o=[],st=[],p={"+":1,"-":1,"*":2,"/":2};for(const v of t)if(/^\d/.test(v))o.push(+v);else if(v==="(")st.push(v);else if(v===")"){while(st.length&&st.at(-1)!=="(")o.push(st.pop());if(st.pop()!=="(")throw Error()}else{while(st.length&&st.at(-1)!=="("&&p[st.at(-1)]>=p[v])o.push(st.pop());st.push(v)}while(st.length){if(st.at(-1)==="(")throw Error();o.push(st.pop())}const a=[];for(const v of o)if(typeof v==="number")a.push(v);else{const b=a.pop(),c=a.pop();if(b===undefined||c===undefined)throw Error();a.push({"+":c+b,"-":c-b,"*":c*b,"/":c/b}[v])}if(a.length!==1||!Number.isFinite(a[0]))throw Error();return a[0]}
function reference(){closeOverlays();const n=document.createElement("div");n.id="referencePanel";n.className="overlay-panel reference-panel";n.innerHTML='<div class="panel-head"><b>Reference sheet</b><button id="closeRef" class="icon-btn">×</button></div><h4>Common formulas</h4><p>Circle: C=2πr, A=πr²</p><p>Triangle: A=½bh</p><p>Rectangle: A=lw</p><p>Prism: V=lwh</p><p>Cylinder: V=πr²h</p><p>Pythagorean: a²+b²=c²</p><p>Slope: m=(y₂−y₁)/(x₂−x₁)</p><p>Distance: d=√((x₂−x₁)²+(y₂−y₁)²)</p>';document.body.append(n);n.querySelector("#closeRef").onclick=()=>n.remove()}

function review(){closeOverlays();const n=document.createElement("div");n.id="reviewModal";n.className="modal-backdrop review-veil";n.setAttribute("role","dialog");n.setAttribute("aria-modal","true");n.setAttribute("aria-labelledby","reviewTitle");const a=bank(),sec=m().section,secNum=sec==="Math"?"2":"1";n.innerHTML=`<div class="modal review-modal"><button class="review-close icon-btn" id="reviewDismiss" aria-label="Close question menu">×</button><h2 id="reviewTitle">Section ${secNum}, Module ${s.mi+1}: ${esc(sec)} Questions</h2><p class="small">Select a question to return to it. Your answers are saved automatically.</p><div class="review-card"><div class="review-head"><div class="review-head-title">Question Status</div><div class="review-legend"><span class="legend-item"><span class="legend-current" aria-hidden="true"></span> Current</span><span class="legend-item"><span class="legend-box" aria-hidden="true"></span> Unanswered</span><span class="legend-item"><span class="legend-ribbon" aria-hidden="true"></span> For Review</span></div></div><div class="review-grid" role="group" aria-label="Review questions">${a.map((_,i)=>`<button class="review-q ${i===s.qi?"current":""} ${answered(i)?"answered":""} ${marked(i)?"marked":""}" data-q="${i}" aria-label="Question ${i+1}${answered(i)?", answered":", unanswered"}${marked(i)?", marked for review":""}">${i+1}</button>`).join("")}</div></div><div class="review-page-action"><button class="btn" id="goReviewPage">Go to Review Page</button></div><div class="modal-actions"><button class="btn pill-blue" id="closeReview2">Return</button><button class="btn pill-blue primary" id="closeReview">Continue</button>${s.harness?`<button class="btn pill-blue primary" id="submitModule">Next</button>`:""}</div></div>`;document.body.append(n);n.querySelectorAll("[data-q]").forEach(b=>b.onclick=()=>go(+b.dataset.q));const closeReview=()=>n.remove();n.querySelector("#reviewDismiss")?.addEventListener("click",closeReview);n.querySelector("#closeReview").onclick=closeReview;n.querySelector("#closeReview2")?.addEventListener("click",closeReview);n.addEventListener("click",e=>{if(e.target===n)closeReview();});n.querySelector("#goReviewPage")?.addEventListener("click",()=>{const target=a.findIndex((_,i)=>marked(i)||!answered(i));if(target>=0){go(target)}else{closeReview();toast("All questions in this module are answered.");}});const sb=n.querySelector("#submitModule");if(sb)sb.onclick=()=>{n.remove();finishModule()}}
function source(x){let h='<div class="source-label">Source</div>';const hasParagraphs=!!x.source?.paragraphs?.length;if(hasParagraphs)h+=`<div class="passage">${x.source.paragraphs.map(p=>`<p>${esc(p)}</p>`).join("")}</div>`;if(x.source?.table)h+=`<div class="data-table"><table><thead><tr>${x.source.table.headers.map(v=>`<th>${esc(v)}</th>`).join("")}</tr></thead><tbody>${x.source.table.rows.map(r=>`<tr>${r.map(v=>`<td>${esc(v)}</td>`).join("")}</tr>`).join("")}</tbody></table></div>`;if(!hasParagraphs&&!x.source?.table)h+='<div class="passage"><p>Use the information in the question to determine the best answer.</p></div>';const hs=s.highlights[qkey()]||[];if(hs.length)h+=`<div class="annotation-list"><b>Saved highlights</b>${hs.map(v=>`<span>“${esc(v)}”</span>`).join("")}</div>`;if(s.notes[qkey()])h+=`<div class="annotation-note"><b>Note:</b> ${esc(s.notes[qkey()])}</div>`;return h}
function choices(x){const v=s.answers[qkey()]||"",e=new Set(s.eliminated[qkey()]||[]);return`<div class="choices" role="radiogroup" aria-label="Answer choices">${x.options.map((o,i)=>`<div class="choice-wrap ${e.has(i)?"eliminated":""}"><button class="eliminate-btn strike-btn" data-eliminate="${i}" aria-label="Cross out choice ${C.letters[i]}" aria-pressed="${String(e.has(i))}">${strikeSvg()}</button><button class="choice ${v===C.letters[i]?"selected":""}" data-answer="${C.letters[i]}" role="radio" aria-checked="${String(v===C.letters[i])}" aria-pressed="${String(v===C.letters[i])}"><span class="choice-bubble">${C.letters[i]}</span><span class="choice-text">${esc(o)}</span></button>${e.has(i)?`<button class="eliminate-btn undo-btn" data-eliminate="${i}">Undo</button>`:""}</div>`).join("")}</div>`}
function shell(i){return`<div class="app-shell">${i}</div>`}
function bookLogo(){return`<img class="ico-logo" src="assets/bluebook-logo.jpg" alt="" aria-hidden="true">`}
function qrSvg(){const rows=["111111101110001000010100001111111","100000101011101001001001001000001","101110100001011010100000101011101","101110101110100100100100101011101","101110100001000011100011101011101","100000100001100110000011001000001","111111101010101010101010101111111","000000001100000111010010100000000","101101110100101101001001101001011","001010000100011001010000011001111","001100111110010010101111101100001","011111011000100001011110000101000","111100110010001010011111000011100","011010010111111001001101010001001","100011111000010001011000101010000","000011010010101100100100100100111","110010110011101000000101011000101","110110001011100110101010110111001","110101100110011100100100010000100","011011000100101001100010100000001","000000110001001010010010010100000","111110010101110110001010011101110","000110100111101100111010011011111","010001011101000100001001110010000","101100101010110011111111111111001","000000001000001100000111100010010","111111101100011001111100101011010","100000101000010101100001100011100","101110100110001011100011111110010","101110101010011011010011000010111","101110101001100110001000000001100","100000100001110001101011011001001","111111101010011001010000010001100"],n=rows.length;let c="";rows.forEach((row,y)=>{for(let x=0;x<n;x++){if(row[x]==="1")c+=`<rect x="${x+4}" y="${y+4}" width="1" height="1"/>`}});return`<svg class="ticket-qr-img" viewBox="0 0 ${n+8} ${n+8}" role="img" aria-label="Admission ticket QR code"><rect width="${n+8}" height="${n+8}" fill="#fff"/><g fill="#111">${c}</g></svg>`}
